import{_ as t,o,c as a,ag as r}from"./chunks/framework.BaNuf0sO.js";const u=JSON.parse('{"title":"AiPartRenderer（内部件 · 仅 API）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agent/src/components/bubble/docs/README-AiPartRenderer.md","filePath":"docs/agent/src/components/bubble/docs/README-AiPartRenderer.md"}'),d={name:"docs/agent/src/components/bubble/docs/README-AiPartRenderer.md"};function i(l,e,n,c,s,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="aipartrenderer-内部件-·-仅-api" tabindex="-1">AiPartRenderer（内部件 · 仅 API） <a class="header-anchor" href="#aipartrenderer-内部件-·-仅-api" aria-label="Permalink to &quot;AiPartRenderer（内部件 · 仅 API）&quot;">​</a></h1><blockquote><p>内部件，[MUST NOT] 当公共组件用（无独立对外使用场景）。非 text part 的默认渲染（C 阶段 REQ-2 新增）：AiMessageList（reasoning/tool-call/file + data-* 缺槽兜底）与 AiBubbleContent（自管路径 <code>item.parts</code>）共用。</p></blockquote><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ 以组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>part</code></td><td><code>AiMessagePart</code>（必填，非 text）</td><td>—</td><td>reasoning / tool-call / file / data-* part</td></tr><tr><td><code>item</code></td><td><code>XBubbleListItemProps?</code></td><td>—</td><td>气泡项（reasoning 标题态取 <code>isAborted</code>；缺省时降级为无中止态）</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p>无</p><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="机制契约" tabindex="-1">机制契约 <a class="header-anchor" href="#机制契约" aria-label="Permalink to &quot;机制契约&quot;">​</a></h2><ul><li><strong>reasoning</strong>：复用 <code>AiThinkBox</code>（与 <code>&lt;think&gt;</code> 内联路径<strong>同一套</strong>标题三态「正在思考 / 已思考(N秒) / 已停止」+ 流式自动展开 / 完成自动折叠 / 手动优先）。<code>isThinking</code> 取 <code>part.state === &quot;streaming&quot;</code>；耗时取 <code>part.thinkTime</code>（q21yfk 判据 4：双路径一致，[MUST NOT] 再维护独立的「思考过程」简易折叠块）</li><li><strong>tool-call</strong>：工具卡（q21yfk 判据 2/3，对标 AI SDK Elements Tool）： <ul><li><strong>默认折叠</strong>，折叠态 = 一行摘要：工具名（mono）+ 入参紧凑单行预览（truncate）+ 状态 pill；</li><li>状态 pill 带图标 + 语义色（streaming=info 旋转 / input-available=warning / output-available=success / output-error=danger / output-denied=warning），色走 <code>--dc-agent-color-*</code> + <code>color-mix</code> 淡底，零自造 var；</li><li>展开态 = 发丝边卡片内「入参 / 结果」分节 <code>pre</code>；<code>errorText</code> 红色展示；</li><li>[MUST NOT] 猜业务人话摘要（「查询天气」这类归消费方 <code>#tool</code> 槽，见批次 D8）</li></ul></li><li><strong>file</strong>：<code>mediaType</code> 为 <code>image/</code> 且带 <code>url</code> → <code>&lt;img&gt;</code>；否则附件占位（文件名或 MIME）</li><li><strong>data-</strong>*：占位文案 <code>[unsupported part: &lt;type&gt;]</code> + console.warn（按 type 去重）——#part 槽由消费方接管时的兜底</li><li>主题变量全走 <code>--dc-agent-*</code>（含 color-primary 派生错误色），零自造变量（规则 14）</li></ul>',14)])])}const b=t(d,[["render",i]]);export{u as __pageData,b as default};
